import { Injectable, signal } from '@angular/core';

const STORAGE_KEY = 'vdin_nav_back_path';

const KNOWN_BACK_PATHS = new Set([
  'bandeja/recibidas',
  'bandeja/subsanadas',
  'bandeja/no-completadas',
  'bandeja/autorizadas',
  'bandeja/aprobadas',
  'bandeja/no-autorizadas',
  'dictaminacion',
  'autorizadas/asignar',
  'autorizadas/por-aprobar',
  'autorizadas/aprobadas',
  'autorizadas/no-aprobadas',
]);

const DEFAULT_BACK_PATH = 'bandeja/recibidas';

function getStoredBackPath(): string | null {
  try {
    const value = sessionStorage.getItem(STORAGE_KEY);
    if (typeof value === 'string' && KNOWN_BACK_PATHS.has(value)) {
      return value;
    }
  } catch {
    // sessionStorage not available or quota exceeded
  }
  return null;
}

@Injectable({ providedIn: 'root' })
export class NavigationHistoryService {
  private readonly currentBackPath = signal<string | null>(getStoredBackPath());

  recordBackPath(backPath: string): void {
    if (!KNOWN_BACK_PATHS.has(backPath)) {
      return;
    }
    try {
      sessionStorage.setItem(STORAGE_KEY, backPath);
    } catch {
      // sessionStorage not available
    }
    this.currentBackPath.set(backPath);
  }

  getBackRoute(portal: 'ejecutivo' | 'inversor', fallback: string, fromQueryParam?: string): string {
    if (portal === 'inversor') {
      return '/inversores/autorizaciones';
    }
    const validFallback = KNOWN_BACK_PATHS.has(fallback) ? fallback : DEFAULT_BACK_PATH;
    const effectiveFromParam = KNOWN_BACK_PATHS.has(fromQueryParam ?? '') ? fromQueryParam! : null;
    const effectiveStored = this.currentBackPath();
    const effectiveBackPath = effectiveFromParam ?? effectiveStored ?? validFallback;
    return '/ejecutivos/' + effectiveBackPath;
  }
}
